 if(!['veinot1997','yao1998','stiger1999','peng1998','shah2001','gerion2001','braun2001','besson2002','dantas2002','yi2002','banerjee2003','schwartz2003','sashchiuk2004','gu2004','nagasaki2004','ribeiro2004','norberg2004'].includes(r.lineage?.source_group))return;
