 if(r.lineage?.source_group==='shah2001'&&entryId)host.append(el('p','The supplied article provides original microscopy and reports crystalline metal cores, but supplies no measured atomic coordinates or refined sample CIF. Hexagonal particle packing is an assembly observation, not a bulk crystal phase. Product cards and molecular conformers are reference illustrations.','guide-notice'));
 if(r.lineage?.source_group==='peng1998'&&entryId)host.append(el('p','No measured phase or atomic coordinates are supplied for these specimens. Identity cards do not reconstruct a crystal lattice. The 8.5 nm CdSe TEM specimen and the optical calibration tables retain separate source contexts; no sample CIF is inferred.','guide-notice'));
